CREATE OR REPLACE FUNCTION private.trg_lock_organization_aka_order_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    private.aka_order_organization_lock_key(new.id)
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.trg_loyalty_from_org_customer_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.customer_id is not distinct from new.customer_id then
    return new;
  end if;

  perform private.reconcile_org_product_loyalty(old.customer_id);
  perform private.reconcile_org_product_loyalty(new.customer_id);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.protect_org_lifecycle_attribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_product_actor bigint;
  v_product_at timestamptz;
begin
  if tg_op = 'INSERT' then
    new.demo_created_by := null;
    new.first_sale_by := null;
    new.demo_created_at := null;
    new.first_sale_at := null;
    return new;
  end if;

  if old.demo_created_at is not null then
    new.demo_created_at := old.demo_created_at;
    new.demo_created_by := old.demo_created_by;
  elsif new.demo_created_at is not null then
    select product.demo_created_by, product.demo_created_at
    into v_product_actor, v_product_at
    from public.org_organization_product as product
    where product.organization_id = new.id
      and product.demo_created_at is not null
    order by product.demo_created_at, product.id
    limit 1;

    if not found
       or new.demo_created_at is distinct from v_product_at
       or new.demo_created_by is distinct from v_product_actor
       or (
         old.demo_created_by is not null
         and v_product_actor is distinct from old.demo_created_by
       ) then
      new.demo_created_at := old.demo_created_at;
      new.demo_created_by := old.demo_created_by;
    else
      new.demo_created_at := v_product_at;
      new.demo_created_by := v_product_actor;
    end if;
  else
    new.demo_created_at := old.demo_created_at;
    new.demo_created_by := old.demo_created_by;
  end if;

  if old.first_sale_at is not null then
    new.first_sale_at := old.first_sale_at;
    new.first_sale_by := old.first_sale_by;
  elsif new.first_sale_at is not null then
    select product.first_sale_by, product.first_sale_at
    into v_product_actor, v_product_at
    from public.org_organization_product as product
    where product.organization_id = new.id
      and product.first_sale_at is not null
    order by product.first_sale_at, product.id
    limit 1;

    if not found
       or new.first_sale_at is distinct from v_product_at
       or new.first_sale_by is distinct from v_product_actor
       or (
         old.first_sale_by is not null
         and v_product_actor is distinct from old.first_sale_by
       ) then
      new.first_sale_at := old.first_sale_at;
      new.first_sale_by := old.first_sale_by;
    else
      new.first_sale_at := v_product_at;
      new.first_sale_by := v_product_actor;
    end if;
  else
    new.first_sale_at := old.first_sale_at;
    new.first_sale_by := old.first_sale_by;
  end if;

  return new;
end
$function$
